e":60,"planned_minutes":60,"instructor_actions":"Play/pause the relevant Academy videos and coach the class: Approved WLD 115 practice-part preparation if time and capacity permit.","student_actions":"Watch together, follow the steps, and retain individual evidence: Nested file/parts and labels as needed; separate course records."}]},{"planner_day_number":21,"title":"Torchmate Academy — Complete independent operator cycle under instructor gates.","objective":"Complete independent operator cycle under instructor gates.","instructor_prep":"Sign in to Torchmate Academy; queue the named videos, ready the CAD station, and review approved machine settings and the supervised cut queue.","safety_focus":"Use the installed Torchmate 4800/FlexCut 80 procedures. Instructor approves every live cut and stops unsafe work.","opening_review":"Recall the prior video, current project status, and one safety or quality check.","demonstration":"Play and pause the instructor-only Academy videos for whole-class follow-along; no separate lecture block.","guided_practice":"Complete independent operator cycle under instructor gates.","independent_practice":"Follow the Academy procedure in CAD or at the machine under instructor direction. CNC cuts may rotate during WLD 115 with direct supervision.","instructor_checks":"Inspection, approved cut, QC and safe closeout.","assessment":"Inspection, approved cut, QC and safe closeout.","teaching_tips":"Record class video playback separately from each student's participation and project evidence. Academy login belongs to the instructor only.","materials_equipment":"Instructor Academy access; display/audio; Torchmate 4800; FlexCut 80; installed CAD/VMD; approved PPE, stock, cut chart and consumables.","evidence_check_for_understanding":"Inspection, approved cut, QC and safe closeout.","outcome_codes":["CLO 1","CLO 2","CLO 3"],"segments":[{"sequence_number":1,"segment_type":"guided_practice","segment_title":"Instructor-played Academy videos and follow-along","start_minute":0,"end_minute":60,"planned_minutes":60,"instructor_actions":"Play/pause the relevant Academy videos and coach the class: Complete independent operator cycle under instructor gates.","student_actions":"Watch together, follow the steps, and retain individual evidence: Inspection, approved cut, QC and safe closeout."}]},{"planner_day_number":22,"title":"Torchmate Academy — Final reflection and portfolio check.","objective":"Final reflection and portfolio check.","instructor_prep":"Sign in to Torchmate Academy; queue the named videos, ready the CAD station, and review approved machine settings and the supervised cut queue.","safety_focus":"Use the installed Torchmate 4800/FlexCut 80 procedures. Instructor approves every live cut and stops unsafe work.","opening_review":"Recall the prior video, current project status, and one safety or quality check.","demonstration":"Play and pause the instructor-only Academy videos for whole-class follow-along; no separate lecture block.","guided_practice":"Final reflection and portfolio check.","independent_practice":"Follow the Academy procedure in CAD or at the machine under instructor direction. CNC cuts may rotate during WLD 115 with direct supervision.","instructor_checks":"Three project records, LTG participation evidence and any remaining deficiencies.","assessment":"Three project records, LTG participation evidence and any remaining deficiencies.","teaching_tips":"Record class video playback separately from each student's participation and project evidence. Academy login belongs to the instructor only.","materials_equipment":"Instructor Academy access; display/audio; Torchmate 4800; FlexCut 80; installed CAD/VMD; approved PPE, stock, cut chart and consumables.","evidence_check_for_understanding":"Three project records, LTG participation evidence and any remaining deficiencies.","outcome_codes":["CLO 1","CLO 4","CLO 7"],"segments":[{"sequence_number":1,"segment_type":"guided_practice","segment_title":"Instructor-played Academy videos and follow-along","start_minute":0,"end_minute":60,"planned_minutes":60,"instructor_actions":"Play/pause the relevant Academy videos and coach the class: Final reflection and portfolio check.","student_actions":"Watch together, follow the steps, and retain individual evidence: Three project records, LTG participation evidence and any remaining deficiencies."}]}]},{"course_code":"WLD 115","guide_name":"WLD 115 Night Level 1 22-Day Instructor Guide","planned_instructional_days":22,"protected_outcomes":{"CLO 1":"Perform safety inspections for GMAW, FCAW, and GTAW equipment.","CLO 2":"Correctly set up GMAW, FCAW, and GTAW power sources, guns, torches, and gas systems.","CLO 3":"Produce GMAW stringer beads and fillet welds in 1F–4F positions.","CLO 4":"Produce FCAW stringer beads and fillet welds following proper parameter control.","CLO 5":"Perform GTAW autogenous welds and filler-metal welds on ferrous and non-ferrous metals.","CLO 6":"Interpret weld quality indicators and apply corrective adjustments to improve technique."},"grade_weights":{"GTAW":35,"GMAW":35,"FCAW":20,"attendance_and_shop_conduct":10},"days":[{"planner_day_number":1,"title":"GTAW — Inspect GTAW stations and gas cylinders","objective":"Inspect GTAW stations and gas cylinders; identify nonconsumable tungsten, torch components, shielding, emergency stops, and the authorized setup sequence.","instructor_prep":"Confirm the approved WPS, equipment, consumables, coupons, and supervised practice stations.","safety_focus":"Check PPE, ventilation, cylinder and electrical setup; stop unsafe work and obtain instructor clearance.","opening_review":"Review the prior day's settings, quality evidence, and one corrective action.","demonstration":"Inspect GTAW stations and gas cylinders; identify nonconsumable tungsten, torch components, shielding, emergency stops, and the authorized setup sequence.","guided_practice":"Instructor checks every station before energizing. Students dry-run torch position and safe shutdown, then establish short, controlled autogenous arcs on clean steel.","independent_practice":"Instructor checks every station before energizing. Students dry-run torch position and safe shutdown, then establish short, controlled autogenous arcs on clean steel.","instructor_checks":"Signed safety/setup checklist; label one baseline coupon. Coach arc length and hand support before speed.","assessment":"Signed safety/setup checklist; label one baseline coupon. Coach arc length and hand support before speed.","teaching_tips":"Coach one observable correction at a time; log settings and label coupons.","materials_equipment":"Approved WPS, PPE, process-specific power source and torch/gun, consumables, gas where applicable, and practice coupons.","evidence_check_for_understanding":"Signed safety/setup checklist; label one baseline coupon. Coach arc length and hand support before speed.","outcome_codes":["CLO 1","CLO 2","CLO 5"],"segments":[{"sequence_number":1,"segment_type":"demonstration","segment_title":"Toolbox talk and demonstration","start_minute":0,"end_minute":25,"planned_minutes":25,"instructor_actions":"Inspect GTAW stations and gas cylinders; identify nonconsumable tungsten, torch components, shielding, emergency stops, and the authorized setup sequence.","student_actions":"Identify the hazard and observe the process demonstration."},{"sequence_number":2,"segment_type":"guided_practice","segment_title":"Guided setup and practice","start_minute":25,"end_minute":60,"planned_minutes":35,"instructor_actions":"Demonstrate, then coach: Instructor checks every station before energizing. Students dry-run torch position and safe shutdown, then establish short, controlled autogenous arcs on clean steel.","student_actions":"Complete supervised setup and first attempt."},{"sequence_number":3,"segment_type":"independent_practice","segment_title":"Practice, coaching, and assessment","start_minute":60,"end_minute":200,"planned_minutes":140,"instructor_actions":"Instructor checks every station before energizing. Students dry-run torch position and safe shutdown, then establish short, controlled autogenous arcs on clean steel.","student_actions":"Practice, adjust one variable, and retain labeled work."},{"sequence_number":4,"segment_type":"other","segment_title":"Evidence and safe closeout","start_minute":200,"end_minute":225,"planned_minutes":25,"instructor_actions":"Check and record: Signed safety/setup checklist; label one baseline coupon. Coach arc length and hand support before speed. Shut down and account for equipment.","student_actions":"Log evidence, shut down safely, and clean the station."}]},{"planner_day_number":2,"title":"GTAW — Demonstrate tungsten selection/preparation, contamination recognition, and clean material preparation","objective":"Demonstrate tungsten selection/preparation, contamination recognition, and clean material preparation.","instructor_prep":"Confirm the approved WPS, equipment, consumables, coupons, and supervised practice stations.","safety_focus":"Check PPE, ventilation, cylinder and electrical setup; stop unsafe work and obtain instructor clearance.","opening_review":"Review the prior day's settings, quality evidence, and one corrective action.","demonstration":"Demonstrate tungsten selection/preparation, contamination recognition, and clean material preparation.","guided_practice":"Prepare approved tungsten and steel coupons; repeat autogenous beads with consistent torch angle and travel. Stop and correct contaminated tips.","independent_practice":"Prepare approved tungsten and steel coupons; repeat autogenous beads with consistent torch angle and travel. Stop and correct contaminated tips.","instructor_checks":"Record settings and one before/after bead; explain why a contaminated tip must be corrected.","assessment":"Record settings and one before/after bead; explain why a contaminated tip must be corrected.","teaching_tips":"Coach one observable correction at a time; log settings and label coupons.","materials_equipment":"Approved WPS, PPE, process-specific power source and torch/gun, consumables, gas where applicable, and practice coupons.","evidence_check_for_understanding":"Record settings and one before/after bead; explain why a contaminated tip must be corrected.","outcome_codes":["CLO 1","CLO 2","CLO 5","CLO 6"],"segments":[{"sequence_number":1,"segment_type":"demonstration","segment_title":"Toolbox talk and demonstration","start_minute":0,"end_minute":25,"planned_minutes":25,"instructor_actions":"Demonstrate tungsten selection/preparation, contamination recognition, and clean material preparation.","student_actions":"Identify the hazard and observe the process demonstration."},{"sequence_number":2,"segment_type":"guided_practice","segment_title":"Guided setup and practice","start_minute":25,"end_minute":60,"planned_minutes":35,"instructor_actions":"Demonstrate, then coach: Prepare approved tungsten and steel coupons; repeat autogenous beads with consistent torch angle and travel. Stop and correct contaminated tips.","student_actions":"Complete supervised setup and first attempt."},{"sequence_number":3,"segment_type":"independent_practice","segment_title":"Practice, coaching, and assessment","start_minute":60,"end_minute":200,"planned_minutes":140,"instructor_actions":"Prepare approved tungsten and steel coupons; repeat autogenous beads with consistent torch angle and travel. Stop and correct contaminated tips.","student_actions":"Practice, adjust one variable, and retain labeled work."},{"sequence_number":4,"segment_type":"other","segment_title":"Evidence and safe closeout","start_minute":200,"end_minute":225,"planned_minutes":25,"instructor_actions":"Check and record: Record settings and one before/after bead; explain why a contaminated tip must be corrected. Shut down and account for equipment.","student_actions":"Log evidence, shut down safely, and clean the station."}]},{"planner_day_number":3,"title":"GTAW — Demonstrate current/polarity selection for the approved material, arc initiation, and heat control","objective":"Demonstrate current/polarity selection for the approved material, arc initiation, and heat control.","instructor_prep":"Confirm the approved WPS, equipment, consumables, coupons, and supervised practice stations.","safety_focus":"Check PPE, ventilation, cylinder and electrical setup; stop unsafe work and obtain instructor clearance.","opening_review":"Review the prior day's settings, quality evidence, and one corrective action.","demonstration":"Demonstrate current/polarity selection for the approved material, arc initiation, and heat control.","guided_practice":"Run autogenous stringers, holding joint fit-up and arc length constant; compare heat input and bead profile.","independent_practice":"Run autogenous stringers, holding joint fit-up and arc length constant; compare heat input and bead profile.","instructor_checks":"Two labeled samples plus a parameter log; coach puddle observation and steady travel.","assessment":"Two labeled samples plus a parameter log; coach puddle observation and steady travel.","teaching_tips":"Coach one observable correction at a time; log settings and label coupons.","materials_equipment":"Approved WPS, PPE, process-specific power source and torch/gun, consumables, gas where applicable, and practice coupons.","evidence_check_for_understanding":"Two labeled samples plus a parameter log; coach puddle observation and steady travel.","outcome_codes":["CLO 2","CLO 5","CLO 6"],"segments":[{"sequence_number":1,"segment_type":"demonstration","segment_title":"Toolbox talk and demonstration","start_minute":0,"end_minute":25,"planned_minutes":25,"instructor_actions":"Demonstrate current/polarity selection for the approved material, arc initiation, and heat control.","student_actions":"Identify the hazard and observe the process demonstration."},{"sequence_number":2,"segment_type":"guided_practice","segment_title":"Guided setup and practice","start_minute":25,"end_minute":60,"planned_minutes":35,"instructor_actions":"Demonstrate, then coach: Run autogenous stringers, holding joint fit-up and arc length constant; compare heat input and bead profile.","student_actions":"Complete supervised setup and first attempt."},{"sequence_number":3,"segment_type":"independent_practice","segment_title":"Practice, coaching, and assessment","start_minute":60,"end_minute":200,"planned_minutes":140,"instructor_actions":"Run autogenous stringers, holding joint fit-up and arc length constant; compare heat input and bead profile.","student_actions":"Practice, adjust one variable, and retain labeled work."},{"sequence_number":4,"segment_type":"other","segment_title":"Evidence and safe closeout","start_minute":200,"end_minute":225,"planned_minutes":25,"instructor_actions":"Check and record: Two labeled samples plus a parameter log; coach puddle observation and steady travel. Shut down and account for equipment.","student_actions":"Log evidence, shut down safely, and clean the station."}]},{"planner_day_number":4,"title":"GTAW — Demonstrate compatible filler identification, feed angle, and timing on clean ferrous coupons","objective":"Demonstrate compatible filler identification, feed angle, and timing on clean ferrous coupons.","instructor_prep":"Confirm the approved WPS, equipment, consumables, coupons, and supervised practice stations.","safety_focus":"Check PPE, ventilation, cylinder and electrical setup; stop unsafe work and obtain instructor clearance.","opening_review":"Review the prior day's settings, quality evidence, and one corrective action.","demonstration":"Demonstrate compatible filler identification, feed angle, and timing on clean ferrous coupons.","guided_practice":"Add filler to established puddles; alternate short coached passes and independent repetition, stopping on contamination.","independent_practice":"Add filler to established puddles; alternate short coached passes and independent repetition, stopping on contamination.","instructor_checks":"One filler-metal coupon with settings and a marked correction; separate torch control from filler timing during coaching.","assessment":"One filler-metal coupon with settings and a marked correction; separate torch control from filler timing during coaching.","teaching_tips":"Coach one observable correction at a time; log settings and label coupons.","materials_equipment":"Approved WPS, PPE, process-specific power source and torch/gun, consumables, gas where applicable, and practice coupons.","evidence_check_for_understanding":"One filler-metal coupon with settings and a marked correction; separate torch control from filler timing during coaching.","outcome_codes":["CLO 2","CLO 5","CLO 6"],"segments":[{"sequence_number":1,"segment_type":"demonstration","segment_title":"Toolbox talk and demonstration","start_minute":0,"end_minute":25,"planned_minutes":25,"instructor_actions":"Demonstrate compatible filler identification, feed angle, and timing on clean ferrous coupons.","student_actions":"Identify the hazard and observe the process demonstration."},{"sequence_number":2,"segment_type":"guided_practice","segment_title":"Guided setup and practice","start_minute":25,"end_minute":60,"planned_minutes":35,"instructor_actions":"Demonstrate, then coach: Add filler to established puddles; alternate short coached passes and independent repetition, stopping on contamination.","student_actions":"Complete supervised setup and first attempt."},{"sequence_number":3,"segment_type":"independent_practice","segment_title":"Practice, coaching, and assessment","start_minute":60,"end_minute":200,"planned_minutes":140,"instructor_actions":"Add filler to established puddles; alternate short coached passes and independent repetition, stopping on contamination.","student_actions":"Practice, adjust one variable, and retain labeled work."},{"sequence_number":4,"segment_type":"other","segment_title":"Evidence and safe closeout","start_minute":200,"end_minute":225,"planned_minutes":25,"instructor_actions":"Check and record: One filler-metal coupon with settings and a marked correction; separate torch control from filler timing during coaching. Shut down and account for equipment.","student_actions":"Log evidence, shut down safely, and clean the station."}]},{"planner_day_number":5,"title":"GTAW — Demonstrate fillet fit-up and tie-in while preserving gas coverage through the end of each weld","objective":"Demonstrate fillet fit-up and tie-in while preserving gas coverage through the end of each weld.","instructor_prep":"Confirm the approved WPS, equipment, consumables, coupons, and supervised practice stations.","safety_focus":"Check PPE, ventilation, cylinder and electrical setup; stop unsafe work and obtain instructor clearance.","opening_review":"Review the prior day's settings, quality evidence, and one corrective action.","demonstration":"Demonstrate fillet fit-up and tie-in while preserving gas coverage through the end of each weld.","guided_practice":"Build fillet welds on approved steel joints; adjust one variable at a time for profile and fusion.","independent_practice":"Build fillet welds on approved steel joints; adjust one variable at a time for profile and fusion.","instructor_checks":"Labeled fillet coupon and instructor notes on tie-in, contamination, and bead consistency.","assessment":"Labeled fillet coupon and instructor notes on tie-in, contamination, and bead consistency.","teaching_tips":"Coach one observable correction at a time; log settings and label coupons.","materials_equipment":"Approved WPS, PPE, process-specific power source and torch/gun, consumables, gas where applicable, and practice coupons.","evidence_check_for_understanding":"Labeled fillet coupon and instructor notes on tie-in, contamination, and bead consistency.","outcome_codes":["CLO 1","CLO 2","CLO 5","CLO 6"],"segments":[{"sequence_number":1,"segment_type":"demonstration","segment_title":"Toolbox talk and demonstration","start_minute":0,"end_minute":25,"planned_minutes":25,"instructor_actions":"Demonstrate fillet fit-up and tie-in while preserving gas coverage through the end of each weld.","student_actions":"Identify the hazard and observe the process demonstration."},{"sequence_number":2,"segment_type":"guided_practice","segment_title":"Guided setup and practice","start_minute":25,"end_minute":60,"planned_minutes":35,"instructor_actions":"Demonstrate, then coach: Build fillet welds on approved steel joints; adjust one variable at a time for profile and fusion.","student_actions":"Complete supervised setup and first attempt."},{"sequence_number":3,"segment_type":"independent_practice","segment_title":"Practice, coaching, and assessment","start_minute":60,"end_minute":200,"planned_minutes":140,"instructor_actions":"Build fillet welds on approved steel joints; adjust one variable at a time for profile and fusion.","student_actions":"Practice, adjust one variable, and retain labeled work."},{"sequence_number":4,"segment_type":"other","segment_title":"Evidence and safe closeout","start_minute":200,"end_minute":225,"planned_minutes":25,"instructor_actions":"Check and record: Labeled fillet coupon and instructor notes on tie-in, contamination, and bead consistency. Shut down and account for equipment.","student_actions":"Log evidence, shut down safely, and clean the station."}]},{"planner_day_number":6,"title":"GTAW — Compare ferrous and approved non-ferrous setup requirements, cleaning, current choices, and filler compatibility","objective":"Compare ferrous and approved non-ferrous setup requirements, cleaning, current choices, and filler compatibility.","instructor_prep":"Confirm the approved WPS, equipment, consumables, coupons, and supervised practice stations.","safety_focus":"Check PPE, ventilation, cylinder and electrical setup; stop unsafe work and obtain instructor clearance.","opening_review":"Review the prior day's settings, quality evidence, and one corrective action.","demonstration":"C