structor_actions":"Supervise and coach: Correct documented weld issues and select coupons, photos, and parameter records.","student_actions":"Correct documented weld issues and select coupons, photos, and parameter records."},{"sequence_number":3,"segment_type":"independent_practice","segment_title":"Welding practice, coaching, and assessment","start_minute":60,"end_minute":200,"planned_minutes":140,"instructor_actions":"Coach, inspect, and assess: Correct documented weld issues and select coupons, photos, and parameter records.","student_actions":"Correct documented weld issues and select coupons, photos, and parameter records."},{"sequence_number":4,"segment_type":"other","segment_title":"Evidence and safe closeout","start_minute":200,"end_minute":225,"planned_minutes":25,"instructor_actions":"Record evidence: Accepted component and portfolio checklist. Complete safe shutdown and handoff.","student_actions":"Submit accepted component and portfolio checklist; log corrections and leave the station safe."}]},{"planner_day_number":23,"title":"Complete final skills check and portfolio","objective":"Complete final skills check and portfolio","instructor_prep":"Prepare the approved project drawings, WPS/test criteria, equipment, material, and individual evidence records.","safety_focus":"PPE, ventilation, fire watch/hot-metal control, machine condition, and instructor release before operation. Stop work on unsafe setup or an unapproved procedure.","opening_review":"Review the prior checkpoint and today's release criteria.","demonstration":"Demonstrate the method and quality check for: complete final skills check and portfolio.","guided_practice":"Demonstrate primary-track quality and submit bend/pipe/capstone evidence with reflection.","independent_practice":"Demonstrate primary-track quality and submit bend/pipe/capstone evidence with reflection.","instructor_checks":"Final skills rubric and verified portfolio","assessment":"Final skills rubric and verified portfolio","teaching_tips":"Coach one measurable correction at a time; retain labeled work and revision history.","materials_equipment":"Approved PPE, project/track drawings, WPS, station equipment, measuring tools, and labeled work records.","evidence_check_for_understanding":"Final skills rubric and verified portfolio","outcome_codes":["CLO 1","CLO 3","CLO 5","CLO 6"],"segments":[{"sequence_number":1,"segment_type":"demonstration","segment_title":"Toolbox talk and demonstration","start_minute":0,"end_minute":25,"planned_minutes":25,"instructor_actions":"Review safety and demonstrate: Complete final skills check and portfolio","student_actions":"Identify hazards, review the prior checkpoint, and observe the demonstration."},{"sequence_number":2,"segment_type":"guided_practice","segment_title":"Guided setup and first attempt","start_minute":25,"end_minute":60,"planned_minutes":35,"instructor_actions":"Supervise and coach: Demonstrate primary-track quality and submit bend/pipe/capstone evidence with reflection.","student_actions":"Demonstrate primary-track quality and submit bend/pipe/capstone evidence with reflection."},{"sequence_number":3,"segment_type":"independent_practice","segment_title":"Welding practice, coaching, and assessment","start_minute":60,"end_minute":200,"planned_minutes":140,"instructor_actions":"Coach, inspect, and assess: Demonstrate primary-track quality and submit bend/pipe/capstone evidence with reflection.","student_actions":"Demonstrate primary-track quality and submit bend/pipe/capstone evidence with reflection."},{"sequence_number":4,"segment_type":"other","segment_title":"Evidence and safe closeout","start_minute":200,"end_minute":225,"planned_minutes":25,"instructor_actions":"Record evidence: Final skills rubric and verified portfolio. Complete safe shutdown and handoff.","student_actions":"Submit final skills rubric and verified portfolio; log corrections and leave the station safe."}]},{"planner_day_number":24,"title":"Close project work and review individual growth","objective":"Close project work and review individual growth","instructor_prep":"Prepare the approved project drawings, WPS/test criteria, equipment, material, and individual evidence records.","safety_focus":"PPE, ventilation, fire watch/hot-metal control, machine condition, and instructor release before operation. Stop work on unsafe setup or an unapproved procedure.","opening_review":"Review the prior checkpoint and today's release criteria.","demonstration":"Demonstrate the method and quality check for: close project work and review individual growth.","guided_practice":"Finish any approved rework, verify shutdown and tool accountability, and review next qualification steps.","independent_practice":"Finish any approved rework, verify shutdown and tool accountability, and review next qualification steps.","instructor_checks":"Final portfolio and individual assessment record","assessment":"Final portfolio and individual assessment record","teaching_tips":"Coach one measurable correction at a time; retain labeled work and revision history.","materials_equipment":"Approved PPE, project/track drawings, WPS, station equipment, measuring tools, and labeled work records.","evidence_check_for_understanding":"Final portfolio and individual assessment record","outcome_codes":["CLO 1","CLO 6"],"segments":[{"sequence_number":1,"segment_type":"demonstration","segment_title":"Toolbox talk and demonstration","start_minute":0,"end_minute":25,"planned_minutes":25,"instructor_actions":"Review safety and demonstrate: Close project work and review individual growth","student_actions":"Identify hazards, review the prior checkpoint, and observe the demonstration."},{"sequence_number":2,"segment_type":"guided_practice","segment_title":"Guided setup and first attempt","start_minute":25,"end_minute":60,"planned_minutes":35,"instructor_actions":"Supervise and coach: Finish any approved rework, verify shutdown and tool accountability, and review next qualification steps.","student_actions":"Finish any approved rework, verify shutdown and tool accountability, and review next qualification steps."},{"sequence_number":3,"segment_type":"independent_practice","segment_title":"Welding practice, coaching, and assessment","start_minute":60,"end_minute":200,"planned_minutes":140,"instructor_actions":"Coach, inspect, and assess: Finish any approved rework, verify shutdown and tool accountability, and review next qualification steps.","student_actions":"Finish any approved rework, verify shutdown and tool accountability, and review next qualification steps."},{"sequence_number":4,"segment_type":"other","segment_title":"Evidence and safe closeout","start_minute":200,"end_minute":225,"planned_minutes":25,"instructor_actions":"Record evidence: Final portfolio and individual assessment record. Complete safe shutdown and handoff.","student_actions":"Submit final portfolio and individual assessment record; log corrections and leave the station safe."}]}]}]$ltg_json$::jsonb;
  guide jsonb;
  day_record jsonb;
  segment_record jsonb;
  course_record record;
  target_guide_id uuid;
  guide_day_id uuid;
  target_curriculum_id uuid;
begin
  for guide in select value from jsonb_array_elements(bundle) loop
    select id, school_id into strict course_record
    from public.courses
    where course_code = guide->>'course_code'
      and school_id = '08ccb452-83ab-482f-bb28-5576e02741b2'::uuid;

    insert into public.course_guides
      (school_id, course_id, guide_name, academic_year, version_label,
       planned_instructional_days, status)
    values
      (course_record.school_id, course_record.id, guide->>'guide_name',
       '2026-2027', '2026-09-23-additional-L1-v1',
       (guide->>'planned_instructional_days')::integer, 'draft')
    on conflict (school_id, course_id, academic_year, version_label)
    do update set guide_name = excluded.guide_name,
                  planned_instructional_days = excluded.planned_instructional_days,
                  status = 'draft', updated_at = now()
    returning id into target_guide_id;

    delete from public.course_guide_days where course_guide_days.guide_id = target_guide_id;

    select id into target_curriculum_id
    from public.course_curriculum
    where course_id = course_record.id
      and version = '2026-2027 additional Level 1 committee syllabus draft'
    limit 1;
    if target_curriculum_id is null then
      insert into public.course_curriculum
        (school_id, course_id, version, curriculum_text, status, locked)
      values
        (course_record.school_id, course_record.id,
         '2026-2027 additional Level 1 committee syllabus draft',
         jsonb_build_object('source', 'user supplied 2026-27 curriculum committee syllabus',
                            'grade_weights', guide->'grade_weights')::text,
         'draft', true)
      returning id into target_curriculum_id;
    end if;
    delete from public.course_outcomes where curriculum_id = target_curriculum_id;
    insert into public.course_outcomes
      (school_id, course_id, curriculum_id, outcome_code, outcome_text, locked)
    select course_record.school_id, course_record.id, target_curriculum_id,
           key, value, true
    from jsonb_each_text(guide->'protected_outcomes');

    for day_record in select value from jsonb_array_elements(guide->'days') loop
      insert into public.course_guide_days
        (school_id, course_id, guide_id, planner_day_number, title, objective,
         instructor_prep, safety_focus, opening_review, demonstration,
         guided_practice, independent_practice, instructor_checks, assessment,
         teaching_tips, materials_equipment, evidence_check_for_understanding)
      values
        (course_record.school_id, course_record.id, target_guide_id,
         (day_record->>'planner_day_number')::integer,
         day_record->>'title', day_record->>'objective',
         day_record->>'instructor_prep', day_record->>'safety_focus',
         day_record->>'opening_review', day_record->>'demonstration',
         day_record->>'guided_practice', day_record->>'independent_practice',
         day_record->>'instructor_checks', day_record->>'assessment',
         day_record->>'teaching_tips', day_record->>'materials_equipment',
         day_record->>'evidence_check_for_understanding')
      returning id into guide_day_id;

      insert into public.course_guide_day_outcomes
        (school_id, course_id, guide_day_id, outcome_id)
      select course_record.school_id, course_record.id, guide_day_id, o.id
      from public.course_outcomes o
      where o.curriculum_id = target_curriculum_id
        and o.outcome_code in
          (select jsonb_array_elements_text(day_record->'outcome_codes'));

      if guide->>'course_code' = 'WLD 114' then
        insert into public.course_guide_day_resources
          (school_id, course_id, guide_day_id, sequence_number, resource_type,
           resource_title, resource_url, resource_notes, required,
           integration_mode, rights_basis, student_safe)
        values
          (course_record.school_id, course_record.id, guide_day_id, 1, 'website',
           'Torchmate Operator Hub — Instructor',
           '/resources/wld114/torchmate-operator-hub.html',
           'Instructor reference. Academy sign-in remains instructor-only; do not share licensed videos with student accounts.',
           false, 'url', 'school_owned', false);
      end if;

      for segment_record in select value from jsonb_array_elements(day_record->'segments') loop
        insert into public.course_guide_day_segments
          (school_id, course_id, guide_day_id, sequence_number, segment_type,
           segment_title, planned_minutes, instructor_actions, student_actions,
           start_minute, end_minute)
        values
          (course_record.school_id, course_record.id, guide_day_id,
           (segment_record->>'sequence_number')::integer,
           segment_record->>'segment_type', segment_record->>'segment_title',
           (segment_record->>'planned_minutes')::integer,
           segment_record->>'instructor_actions', segment_record->>'student_actions',
           (segment_record->>'start_minute')::integer,
           (segment_record->>'end_minute')::integer);
      end loop;
    end loop;
  end loop;
end
$ltg$;
